import { createStore } from 'vuex';

// 从 localStorage 中恢复 Token
const token = localStorage.getItem("token");

export default createStore({
  state: {
    user: null, // 存储用户信息
    token: token || null, // 存储 Token，初始化时从 localStorage 中恢复
  },
  mutations: {
    // 设置用户信息
    setUser(state, user) {
      state.user = user;
    },
    // 设置 Token
    setToken(state, token) {
      state.token = token;
      localStorage.setItem("token", token); // 将 Token 存储到 localStorage
    },
    // 清除用户信息
    clearUser(state) {
      state.user = null;
    },
    // 清除 Token
    clearToken(state) {
      state.token = null;
      localStorage.removeItem("token"); // 清除 localStorage 中的 Token
    },
  },
  actions: {
    // 登录
    login({ commit }, { user, token }) {
      commit('setUser', user);
      commit('setToken', token);
      localStorage.setItem("token", token); // 将 token 存入 localStorage
    },
    // 退出登录
    logout({ commit }) {
      commit('clearUser');
      commit('clearToken');
      localStorage.removeItem("token"); // 清除 token
    },
  },
  getters: {
    // 获取用户信息
    user: (state) => state.user,
    // 获取 Token
    token: (state) => state.token,
  },
});
